ROOT=Path(__file__).resolve().parents[1]
def panel(title,ask,tell,formula=None,visual=None,check=None):
 p={'title':title,'ask':ask,'tell':tell}
 if formula:p['formula']=formula
 if visual:p['visual']=visual
 if check:p['check']=check
 return p
def check(prompt,options,correct,why):return {'prompt':prompt,'options':options,'correct':correct,'why':why}
